<template>
  <div class="page-shell">
    <div class="page-title"><div><span class="eyebrow">TRAINING PROGRAM</span><h1>课程与排课</h1><p>{{ canWriteCourse ? '维护课程模板，安排教练与上课时间' : '查看本场馆课程模板与近期排课' }}</p></div><el-button v-if="canWriteCourse" type="primary" size="large" @click="openCourse"><el-icon><Plus /></el-icon> 新增课程</el-button></div>
    <div class="section-head"><h3>课程库</h3><span>{{ courses.length }} 个课程模板</span></div>
    <div class="course-grid">
      <article v-for="course in courses" :key="course.id" class="course-card">
        <div class="course-accent" :class="course.type.toLowerCase()" />
        <div class="course-top"><span class="tag-group"><el-tag effect="plain">{{ typeText(course.type) }}</el-tag><el-tag v-if="isSuperAdmin" effect="plain" type="info">{{ venueName(course.venueId) }}</el-tag></span><span>¥{{ course.fee }}</span></div>
        <h3>{{ course.name }}</h3><p>{{ course.description || '暂无课程简介' }}</p>
        <div class="course-meta"><span><el-icon><Timer /></el-icon>{{ course.durationMinutes }} 分钟</span><span><el-icon><User /></el-icon>{{ course.maxCapacity }} 人</span><span>{{ intensityText(course.intensity) }}</span></div>
        <el-button v-if="canWriteCourse" link type="primary" @click="openEdit(course)">编辑课程</el-button>
      </article>
    </div>
    <div class="section-head schedule-head"><div><h3>近期排课</h3><span>未来 30 天课程安排</span></div><el-button v-if="canWriteSchedule" @click="openSchedule"><el-icon><Calendar /></el-icon> 新增排课</el-button></div>
    <el-card shadow="never" class="table-card"><el-table v-loading="loading" :data="schedules">
      <el-table-column label="时间" min-width="190"><template #default="{row}"><strong>{{ formatDate(row.scheduledStartTime) }}</strong><small>{{ formatTime(row.scheduledStartTime) }} - {{ formatEndTime(row) }}</small></template></el-table-column>
      <el-table-column v-if="isSuperAdmin" label="门店" min-width="120"><template #default="{row}">{{ venueName(row.venueId) }}</template></el-table-column>
      <el-table-column label="课程" min-width="160"><template #default="{row}">{{ row.course?.name }}</template></el-table-column>
      <el-table-column label="教练" min-width="160"><template #default="{row}"><template v-if="row.coachId">{{ row.coachName }}</template><template v-else-if="row.course?.type==='PRIVATE'"><el-tag type="danger" size="small">未绑定教练账号</el-tag><small class="warn-line">私教课必须绑定教练，否则会员无法预约</small></template><span v-else class="muted">{{ row.coachName || '—' }}</span></template></el-table-column>
      <el-table-column label="预约进度" min-width="190"><template #default="{row}"><div class="capacity"><el-progress :percentage="Math.round(row.enrolledCount / row.maxStudents * 100)" :stroke-width="7" :show-text="false"/><span>{{ row.enrolledCount }}/{{ row.maxStudents }}</span></div></template></el-table-column>
      <el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="row.status==='SCHEDULED'?'success':'info'">{{ row.status==='SCHEDULED'?'可预约':'已结束' }}</el-tag></template></el-table-column>
      <el-table-column v-if="canWriteSchedule" label="操作" width="140" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openEditSchedule(row)">编辑</el-button><el-button link type="danger" @click="removeSchedule(row)">删除</el-button></template></el-table-column>
    </el-table></el-card>

    <el-dialog v-model="courseDialog" :title="editingId ? '编辑课程' : '新增课程'" width="620px"><el-form ref="courseFormRef" :model="courseForm" :rules="courseRules" label-width="90px">
      <el-form-item label="课程名称" prop="name"><el-input v-model="courseForm.name" /></el-form-item>
      <el-form-item label="课程类型" prop="type"><el-select v-model="courseForm.type" style="width:100%"><el-option label="团体课" value="GROUP"/><el-option label="常规课" value="REGULAR"/><el-option label="私教课" value="PRIVATE"/></el-select></el-form-item>
      <el-form-item v-if="isSuperAdmin" label="所属场馆" prop="venueId"><el-select v-model="courseForm.venueId" style="width:100%"><el-option v-for="v in venues" :key="v.id" :label="v.name" :value="v.id" /></el-select></el-form-item>
      <el-form-item label="课程简介"><el-input v-model="courseForm.description" type="textarea" :rows="3" /></el-form-item>
      <el-row :gutter="12"><el-col :span="8"><el-form-item label="时长" prop="durationMinutes" label-width="52px"><el-input-number v-model="courseForm.durationMinutes" :min="15" :max="300" controls-position="right" style="width:100%" /></el-form-item></el-col><el-col :span="8"><el-form-item label="容量" prop="maxCapacity" label-width="52px"><el-input-number v-model="courseForm.maxCapacity" :min="1" :max="500" controls-position="right" style="width:100%" /></el-form-item></el-col><el-col :span="8"><el-form-item label="价格" prop="fee" label-width="52px"><el-input-number v-model="courseForm.fee" :min="0" controls-position="right" style="width:100%" /></el-form-item></el-col></el-row>
      <el-form-item label="强度"><el-radio-group v-model="courseForm.intensity"><el-radio-button label="LOW">低</el-radio-button><el-radio-button label="MEDIUM">中</el-radio-button><el-radio-button label="HIGH">高</el-radio-button></el-radio-group></el-form-item>
      <div class="form-hint">时长 15 ~ 300 分钟，容量 1 ~ 500 人，价格不能为负。</div>
    </el-form><template #footer><div class="dialog-footer"><el-button v-if="editingId && canWriteCourse" type="danger" plain :loading="saving" @click="removeCourse">删除课程</el-button><span class="footer-right"><el-button @click="courseDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveCourse">保存</el-button></span></div></template></el-dialog>

    <el-dialog v-model="scheduleDialog" :title="editingScheduleId ? '编辑排课' : '新增排课'" width="560px"><el-form ref="scheduleFormRef" :model="scheduleForm" :rules="scheduleRules" label-width="90px"><el-form-item v-if="isSuperAdmin" label="所属场馆" prop="venueId"><el-select v-model="scheduleForm.venueId" style="width:100%" @change="onScheduleVenueChange"><el-option v-for="v in venues" :key="v.id" :label="v.name" :value="v.id" /></el-select></el-form-item><el-form-item label="课程" prop="courseId"><el-select v-model="scheduleForm.courseId" style="width:100%" :placeholder="scheduleCourses.length ? '请选择课程' : '该场馆暂无课程模板，请先在课程库新增'"><el-option v-for="c in scheduleCourses" :key="c.id" :label="c.name" :value="c.id" /></el-select><div v-if="editingScheduleId" class="form-hint">更换课程时，该排课会跟随新课程所属门店</div></el-form-item><el-alert v-if="privatePackageMissing" type="warning" :closable="false" style="margin-bottom:14px" title="本门店暂无在售私教课包" description="私教课需要会员先持有私教课包才能预约。建议先在「会籍与商业中心 → 会籍商品」上架私教课包，否则会员约不了这节课。" /><el-form-item label="教练" prop="coachId"><el-select v-model="scheduleForm.coachId" style="width:100%" filterable :placeholder="coaches.length ? '请选择教练账号' : '暂无教练账号，请先在员工账号里创建教练'"><el-option v-for="k in coaches" :key="k.id" :label="k.name" :value="k.id" /></el-select><div class="form-hint">必须绑定真实教练账号，否则教练工作台看不到这条排课</div></el-form-item><el-form-item label="开始时间" prop="scheduledStartTime"><el-date-picker v-model="scheduleForm.scheduledStartTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%" /></el-form-item><el-form-item label="结束时间" prop="scheduledEndTime"><el-date-picker v-model="scheduleForm.scheduledEndTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%" /><div class="form-hint">按课程时长自动带出，可手动调整</div></el-form-item><el-form-item label="容量"><el-input-number v-model="scheduleForm.maxStudents" :min="1" /></el-form-item></el-form><template #footer><el-button @click="scheduleDialog=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!scheduleCourses.length || !coaches.length" @click="saveSchedule">{{ editingScheduleId ? '保存修改' : '创建排课' }}</el-button></template></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'; import { ElMessage, ElMessageBox, type FormInstance, type FormRules } from 'element-plus'; import { Calendar, Plus, Timer, User } from '@element-plus/icons-vue'; import { createCourse, createSchedule, deleteCourse, deleteSchedule, listCoaches, listCourses, listSchedules, updateCourse, updateSchedule, type CoachOption, type Course, type Schedule } from '@/api/modules/course'
import { listVenues, type Venue } from '@/api/modules/venue'
import { listProducts, type Product } from '@/api/modules/commercial'
import { hasPermission, hasRole } from '@/utils/auth'
const loading=ref(false),saving=ref(false),courseDialog=ref(false),scheduleDialog=ref(false),editingId=ref<number|null>(null),editingScheduleId=ref<number|null>(null); const courses=ref<Course[]>([]),schedules=ref<Schedule[]>([]),venues=ref<Venue[]>([]),coaches=ref<CoachOption[]>([]),products=ref<Product[]>([]); const courseFormRef=ref<FormInstance>(),scheduleFormRef=ref<FormInstance>()
const canWriteCourse=hasPermission('COURSE_WRITE'),canWriteSchedule=hasPermission('SCHEDULE_WRITE'),isSuperAdmin=hasRole('SUPER_ADMIN'),canReadProduct=hasPermission('PRODUCT_READ')
const blankCourse=()=>({name:'',type:'GROUP',description:'',durationMinutes:60,intensity:'MEDIUM',maxCapacity:20,fee:0,status:'ACTIVE',venueId:undefined as number|undefined}); const courseForm=reactive(blankCourse()); const scheduleForm=reactive({venueId:undefined as number|undefined,courseId:undefined as number|undefined,coachId:undefined as number|undefined,scheduledStartTime:'',scheduledEndTime:'',maxStudents:20})
const courseRules:FormRules={venueId:isSuperAdmin?[{required:true,message:'请选择所属场馆'}]:[],name:[{required:true,message:'请输入课程名称'}],type:[{required:true,message:'请选择课程类型'}],durationMinutes:[{required:true,message:'请输入时长'},{type:'number',min:15,max:300,message:'时长需在 15 ~ 300 分钟之间'}],maxCapacity:[{required:true,message:'请输入容量'},{type:'number',min:1,max:500,message:'容量需在 1 ~ 500 人之间'}],fee:[{required:true,message:'请输入价格'},{type:'number',min:0,message:'价格不能为负数'}]}; const scheduleRules:FormRules={venueId:isSuperAdmin?[{required:true,message:'请选择所属场馆'}]:[],courseId:[{required:true,message:'请选择课程'}],coachId:[{required:true,message:'请选择教练账号'}],scheduledStartTime:[{required:true,message:'请选择开始时间'}],scheduledEndTime:[{required:true,message:'请选择结束时间'}]}
const scheduleCourses=computed(()=>scheduleForm.venueId==null?courses.value:courses.value.filter(c=>c.venueId===scheduleForm.venueId))
const privatePackageMissing=computed(()=>{
  const course=courses.value.find(c=>c.id===scheduleForm.courseId)
  if(course?.type!=='PRIVATE')return false
  const venueId=scheduleForm.venueId??course.venueId
  return !products.value.some(p=>p.productType==='PRIVATE_PACKAGE'&&p.status==='ACTIVE'&&(venueId==null||p.venueId===venueId))
})
const venueName=(id?:number|null)=>venues.value.find(v=>v.id===id)?.name??(id?`场馆 ${id}`:'—')
const syncScheduleEnd=()=>{const course=courses.value.find(c=>c.id===scheduleForm.courseId);if(!course||!scheduleForm.scheduledStartTime)return;const start=new Date(scheduleForm.scheduledStartTime);if(Number.isNaN(start.getTime()))return;const pad=(n:number)=>String(n).padStart(2,'0');const end=new Date(start.getTime()+course.durationMinutes*60000);scheduleForm.scheduledEndTime=`${end.getFullYear()}-${pad(end.getMonth()+1)}-${pad(end.getDate())}T${pad(end.getHours())}:${pad(end.getMinutes())}:00`}
watch(()=>[scheduleForm.courseId,scheduleForm.scheduledStartTime],syncScheduleEnd)
const onScheduleVenueChange=()=>{scheduleForm.courseId=courses.value.find(c=>c.venueId===scheduleForm.venueId)?.id;syncScheduleEnd()}
const load=async()=>{loading.value=true;try{const [c,s,v,k,p]=await Promise.all([listCourses(),listSchedules(),listVenues().catch(()=>null),listCoaches().catch(()=>null),canReadProduct?listProducts().catch(()=>null):Promise.resolve(null)]);courses.value=c.data;schedules.value=s.data;venues.value=Array.isArray(v?.data)?v.data:[];coaches.value=Array.isArray(k?.data)?k.data:[];products.value=Array.isArray(p?.data)?p.data:[]}finally{loading.value=false}}
const openCourse=()=>{Object.assign(courseForm,blankCourse(),{venueId:venues.value[0]?.id});editingId.value=null;courseDialog.value=true}; const openEdit=(c:Course)=>{Object.assign(courseForm,c);editingId.value=c.id;courseDialog.value=true}; const openSchedule=()=>{editingScheduleId.value=null;const venueId=isSuperAdmin?(venues.value.find(v=>courses.value.some(c=>c.venueId===v.id))?.id??venues.value[0]?.id):undefined;Object.assign(scheduleForm,{venueId,courseId:courses.value.find(c=>venueId==null||c.venueId===venueId)?.id,coachId:undefined,scheduledStartTime:'',scheduledEndTime:'',maxStudents:20});scheduleDialog.value=true}; const openEditSchedule=(row:Schedule)=>{editingScheduleId.value=row.id;Object.assign(scheduleForm,{venueId:row.venueId,courseId:row.courseId,coachId:row.coachId??undefined,scheduledStartTime:row.scheduledStartTime,scheduledEndTime:row.scheduledEndTime,maxStudents:row.maxStudents});scheduleDialog.value=true}
const clampNumber=(v:any,min:number,max:number)=>typeof v==='number'&&Number.isFinite(v)?Math.min(max,Math.max(min,v)):v
const removeCourse=async()=>{if(!editingId.value)return;try{await ElMessageBox.confirm(`确认删除课程「${courseForm.name}」？该操作不可恢复。`,'删除课程',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'取消'})}catch{return}saving.value=true;try{await deleteCourse(editingId.value);ElMessage.success('课程已删除');courseDialog.value=false;await load()}finally{saving.value=false}}
const saveCourse=async()=>{if(!await courseFormRef.value?.validate().catch(()=>false))return;saving.value=true;try{const payload={...courseForm,durationMinutes:clampNumber(courseForm.durationMinutes,15,300),maxCapacity:clampNumber(courseForm.maxCapacity,1,500),fee:clampNumber(courseForm.fee,0,Number.MAX_SAFE_INTEGER)};editingId.value?await updateCourse(editingId.value,payload):await createCourse(payload);ElMessage.success('课程已保存');courseDialog.value=false;await load()}finally{saving.value=false}}
const removeSchedule=async(row:Schedule)=>{try{await ElMessageBox.confirm(`确认删除排课「${row.course?.name||''} ${formatDate(row.scheduledStartTime)}」？`,'删除排课',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'取消'})}catch{return}saving.value=true;try{await deleteSchedule(row.id);ElMessage.success('排课已删除');await load()}finally{saving.value=false}}
const saveSchedule=async()=>{if(!await scheduleFormRef.value?.validate().catch(()=>false)||!scheduleForm.courseId||!scheduleForm.coachId)return;saving.value=true;try{const base={courseId:scheduleForm.courseId,coachId:scheduleForm.coachId,coachName:coaches.value.find(c=>c.id===scheduleForm.coachId)?.name??'',scheduledStartTime:scheduleForm.scheduledStartTime,scheduledEndTime:scheduleForm.scheduledEndTime,maxStudents:scheduleForm.maxStudents};if(editingScheduleId.value){await updateSchedule(editingScheduleId.value,base);ElMessage.success('排课已更新')}else{await createSchedule({...base,venueId:scheduleForm.venueId});ElMessage.success('排课已创建')}scheduleDialog.value=false;await load()}finally{saving.value=false}}
const typeText=(v:string)=>({GROUP:'团体课',REGULAR:'常规课',PRIVATE:'私教课'}[v]||v);const intensityText=(v:string)=>({LOW:'低强度',MEDIUM:'中强度',HIGH:'高强度'}[v]||v);const formatDate=(v:string)=>new Date(v).toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'short'});const formatTime=(v:string)=>new Date(v).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});const formatEndTime=(row:Schedule)=>{const s=new Date(row.scheduledStartTime),e=new Date(row.scheduledEndTime);return s.toDateString()===e.toDateString()?formatTime(row.scheduledEndTime):`${e.getMonth()+1}月${e.getDate()}日 ${formatTime(row.scheduledEndTime)}`};onMounted(load)
</script>

<style scoped>
.page-title,.section-head,.schedule-head,.course-top,.course-meta,.capacity{display:flex;align-items:center;justify-content:space-between}.page-title{margin-bottom:30px}.eyebrow{color:#2768ff;font-size:11px;font-weight:800;letter-spacing:1.5px}.page-title h1{margin:4px 0 6px;font-size:28px;color:#172033}.page-title p,.section-head span{color:#8490a4;font-size:14px}.section-head{margin:0 0 14px}.section-head h3{margin:0;color:#202a3d}.course-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.course-card{position:relative;overflow:hidden;padding:20px;background:#fff;border:1px solid #e9edf5;border-radius:16px}.course-accent{position:absolute;left:0;top:0;right:0;height:4px;background:#2768ff}.course-accent.private{background:#8759e8}.course-accent.regular{background:#22b887}.course-top>span:last-child{font-weight:800;color:#182238}.course-card h3{margin:18px 0 8px}.course-card p{height:44px;color:#7d8798;font-size:13px;line-height:1.65}.course-meta{justify-content:flex-start;gap:14px;padding:14px 0;color:#536078;font-size:12px}.course-meta span{display:flex;align-items:center;gap:4px}.schedule-head{margin-top:30px}.schedule-head>div span{display:block;margin-top:5px}.table-card{border-radius:16px}.table-card small{display:block;margin-top:5px;color:#8490a4}.capacity{gap:12px}.capacity .el-progress{flex:1}.capacity span{font-size:12px;color:#758196}.tag-group{display:flex;align-items:center;gap:6px}.dialog-footer{display:flex;align-items:center}.footer-right{display:flex;margin-left:auto}.form-hint{margin-top:6px;color:#8490a4;font-size:12px;line-height:1.4}.warn-line{color:#d94a4a!important}@media(max-width:1100px){.course-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.course-grid{grid-template-columns:1fr}.page-title{align-items:flex-end}}
</style>
